 void newGroup(){EditText name=new EditText(this);name.setSingleLine();name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(60)});new AlertDialog.Builder(this).setTitle(R.string.new_group).setMessage(R.string.group_live_note).setView(name).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.new_group,(d,n)->{try{String text=name.getText().toString().trim();if(text.isEmpty())return;JSONObject g=LocalGroups.create(text);openGroup(g);}catch(Exception ignored){}}).show();}
