 void render(){content.removeAllViews();JSONArray a=tab.equals("groups")?LocalGroups.all():Store.peers();ArrayList<JSONObject> entries=new ArrayList<>();for(int i=0;i<a.length();i++)if(a.optJSONObject(i)!=null)entries.add(a.optJSONObject(i));Collections.sort(entries,(x,y)->Long.compare(lastTime(y),lastTime(x)));int count=0;for(JSONObject p:entries){String id=p.optString("id"),name=p.optString("name");if(!(name+p.optString("username")).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;boolean group=tab.equals("groups");JSONArray t=Store.thread((group?"live_":"")+id);JSONObject m=t.optJSONObject(t.length()-1);long read=0;try{read=Long.parseLong(Store.get((group?"groupRead_":"read_")+id,"0"));}catch(Exception ignored){}boolean fresh=m!=null&&!m.optBoolean("me")&&m.optLong("ts")>read;if(unread&&!fresh)continue;LinearLayout row=Ui.row(this);Ui.pad(row,18,13,18,13,this);row.addView(Profile.avatar(this,p,50));LinearLayout meta=Ui.col(this);Ui.pad(meta,13,0,8,0,this);TextView title=Ui.t(this,name,16,Ui.text,App.cairoSB);title.setSingleLine();meta.addView(title);String preview=group&&!p.optBoolean("joined")?getString(R.string.join_group):m==null?(group?getString(R.string.group_live_short):getString(R.string.start_chat)):m.optString("kind").equals("file")?"📎 "+m.optString("name"):m.optString("body");TextView sub=Ui.t(this,preview,12,Ui.dim,App.cairo);sub.setSingleLine();sub.setEllipsize(android.text.TextUtils.TruncateAt.END);meta.addView(sub);row.addView(meta,Ui.lpw(1));LinearLayout tail=Ui.col(this);if(m!=null)tail.addView(plain(new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(m.optLong("ts"))),10,fresh?Ui.accent:Ui.dim));if(fresh)tail.addView(plain("●",15,Ui.accent));row.addView(tail);row.setOnClickListener(v->{if(group)openGroup(p);else{Store.set("read_"+id,String.valueOf(System.currentTimeMillis()));Intent intent=new Intent(this,ChatActivity.class);intent.putExtra("peer",id);startActivity(intent);}});content.addView(row);count++;}if(count==0){TextView empty=Ui.sub(this,getString(tab.equals("groups")?R.string.groups_empty:R.string.empty_chat_list));Ui.pad(empty,24,28,24,12,this);content.addView(empty);if(tab.equals("groups")){TextView create=Ui.cta(this,getString(R.string.new_group));content.addView(create);create.setOnClickListener(v->newGroup());}}}
